import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
print("Archive entries:")
for n in z.namelist():
    print(" ", n)

def parse_sheet_xml(data):
    root = ET.fromstring(data)
    rows = []
    for row in root.findall('.//m:row', NS):
        cells = {}
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            col = re.match(r'[A-Z]+', ref).group()
            t = c.get('t')
            v = c.find('m:v', NS)
            val = None
            if t == 'inlineStr':
                is_el = c.find('m:is', NS)
                if is_el is not None:
                    val = ''.join(x.text or '' for x in is_el.findall('.//m:t', NS))
            elif v is not None:
                raw = v.text
                if t == 's':
                    val = shared[ int(raw) ]
                elif t == 'b':
                    val = raw == '1'
                else:
                    val = raw
            cells[col] = val
        rows.append(cells)
    return rows

# Shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    ss_root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in ss_root.findall('m:si', NS):
        shared.append(''.join(x.text or '' for x in si.findall('.//m:t', NS)))

# Workbook sheet names -> r:id
wb_root = ET.fromstring(z.read('xl/workbook.xml'))
rid_to_name = {}
for sh in wb_root.findall('.//m:sheet', NS):
    rid_to_name[sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')] = sh.get('name')

# r:id -> target path
rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels_root.findall('{http://schemas.openxmlformats.org/package/2006/relationships}Relationship'):
    rid_to_target[rel.get('Id')] = rel.get('Target')

grand = 0.0
for rid, name in rid_to_name.items():
    target = rid_to_target[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    data = z.read(target)
    rows = parse_sheet_xml(data)
    print(f"\n=== Sheet: {name} ===")
    for r in rows:
        print(r)
    total = 0.0
    for r in rows:
        for col, val in r.items():
            if val is not None:
                try:
                    total += float(val)
                except (ValueError, TypeError):
                    pass
    grand += total
    print(f"Sheet '{name}' numeric total: {total:.2f}")

print(f"\nGRAND TOTAL (all sheets, all numeric cells): {grand:.2f}")

